UPDATE order_items
SET after_sale_status = #{status}, after_sale_id = #{afterSaleId}
WHERE id = #{orderItemId} AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM order_items
WHERE order_id = #{orderId} AND is_deleted = 0 AND after_sale_status != #{status}

