UPDATE products
SET stock = stock + #{quantity}
WHERE id = #{productId}

UPDATE product_sku
SET stock = stock + #{quantity}, update_time = NOW()
WHERE id = #{skuId}

UPDATE orders
SET order_status = #{status}, updated_at = #{now}
WHERE id = #{orderId} AND is_deleted = 0
